    listActivityForSubject(org.id, "issue", found.id),
    findUserById(found.authorId),
    found.assigneeId === null
      ? Promise.resolve<User | null>(null)
      : findUserById(found.assigneeId),
  ]);

  if (author === null) {
    notFound();
  }

  const actors: Record<string, User> = {};
