  });
  // Store an instant safely inside the chosen local calendar day. Its exact
  // time is immaterial because overdue checks compare local calendar dates.
  return toIsoTimestamp(new Date(new Date(startOfLocalDate(year, month, day, timeZone)).getTime() + 12 * 60 * 60 * 1000));
}

